WHERE b."A3" LIKE '26410%' AND (b."A13"::text ~ '^[0-9]{4}') AND LEFT(regexp_replace(b."A13"::text, '[^0-9]', '', 'g'), 4)::int BETWEEN 1980 AND 1989;

SELECT 100 * COUNT(*) FILTER (WHERE (b."A26"::float8 >= 10 AND (b."A13"::text ~ '^[0-9]{4}') AND LEFT(regexp_replace(b."A13"::text, '[^0-9]', '', 'g'), 4)::int <= 1995))::float8 / NULLIF(COUNT(*) FILTER (WHERE (b."A26"::float8 >= 10 AND (b."A13"::text ~ '^[0-9]{4}') AND LEFT(regexp_replace(b."A13"::text, '[^0-9]', '', 'g'), 4)::int <= 1995)), 0) AS "ratio_pct"
FROM "AL_D010_26_20250704" b
WHERE b."A3" LIKE '26410%';

